head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getUncheckedJSON]<br/>특정 Body Column 이 체크 해제 상태인 Row 의 데이터를 JSON 객체 배열로 반환합니다.",
    "validation" : [
        "DataList 가 rowNumData=true 인 경우 반환값의 마지막 Key 로 'rowNum' 이 추가되고 Row 의 순번(인덱스+1)값을 가져야 합니다.",
        "DataList 가 nullYN=true 일때 Column 값이 빈 문자열이면, nullYNType 속성값이 'null' 이면 null 값으로, 'exclude' 이면 JSON 에서 제외되어야 합니다.",
        "DataList 가 useNull=false 이면 null 값은 빈 문자열('')로 변환되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : con_dataListOption 선택값에 따라 DataList 를 해당 속성(rowNumData / nullYN+nullYNType / useNull)으로 동적 생성
//  - DataList 속성은 dynamicCreate 미지원 → DataList XML 문자열에 직접 속성을 주입하여 $p.data.create 로 생성
//  - emptyCol : 체크 해제(chk=0) Row 에 빈 문자열("")/null 을 섞어 nullYN / useNull @spec 검증용 데이터로 사용
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con 선택값 (DataList 생성 속성 옵션)
    let opt = con_dataListOption.getValue();

    // DataList / Column 에 적용할 속성 결정
    // - rowNumData=true       : DataList 속성 (반환 객체 마지막 Key 로 rowNum 추가)
    // - nullYN=true(Column) + nullYNType=null/exclude(DataList) : 빈 문자열 Column 별도 처리
    // - useNull=false(DataList): null 값을 빈 문자열("")로 변환
    let dltAttr = "";          // DataList 태그 속성
    let emptyColNullYN = "";   // emptyCol Column 의 nullYN 속성
    let labelText = "";
    if (opt === "rowNumData") {
        dltAttr = ' rowNumData="true"';
        labelText = "DataList rowNumData=true → 체크 해제된 Row 반환 객체의 마지막 Key 로 rowNum(인덱스+1) 추가. (chk=0 → Row1=2, Row3=4)";
    } else if (opt === "nullYN_null") {
        dltAttr = ' nullYNType="null"';
        emptyColNullYN = ' nullYN="true"';
        labelText = "emptyCol nullYN=true + DataList nullYNType=null → emptyCol 빈 문자열은 null 값으로 반환.";
    } else if (opt === "nullYN_exclude") {
        dltAttr = ' nullYNType="exclude"';
        emptyColNullYN = ' nullYN="true"';
        labelText = "emptyCol nullYN=true + DataList nullYNType=exclude → emptyCol 빈 문자열은 JSON 에서 제외.";
    } else if (opt === "useNull") {
        dltAttr = ' useNull="false"';
        labelText = "DataList useNull=false → emptyCol 의 null 값은 빈 문자열('')로 변환되어 반환.";
    } else {
        labelText = "기본 (DataList 속성 미적용) → emptyCol 빈 문자열/null 은 그대로 빈 문자열('')로 반환.";
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + labelText + '"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    //  - chk      : checkbox 원본값(1/0) → 조회 대상 Column
    //  - name     : text (항상 값 존재)
    //  - emptyCol : text, nullYN 검증 대상 (체크 해제 Row1="" 빈 문자열, Row3=null) → emptyColNullYN 주입
    //  - birth    : text (항상 값 존재)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map"' + dltAttr + '>';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="emptyCol" name="emptyCol" dataType="text"' + emptyColNullYN + '></w2:column>';
    strDlt += '<w2:column id="birth" name="birth" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // chk 체크/미체크 혼합 4행 (chk=1 → 체크된 Row, chk=0 → 미체크 Row 반환)
    //  - 미체크 Row(1,3) 의 emptyCol 에 빈 문자열("")/null 을 배치하여 nullYN/useNull @spec 을 반환값으로 검증
    //    Row1.emptyCol = ""(빈 문자열), Row3.emptyCol = null
    let jsonData = [
        { "chk": "1", "name": "HONG", "emptyCol": "H",  "birth": "19850315" },
        { "chk": "0", "name": "LEE",  "emptyCol": "",   "birth": "19880101" },
        { "chk": "1", "name": "KIM",  "emptyCol": "K",  "birth": "19900720" },
        { "chk": "0", "name": "PARK", "emptyCol": null, "birth": "19951225" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    // target 생성 (Header 4컬럼 - chk(checkbox) / name / emptyCol / birth)
    // 마지막 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:560px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getUncheckedJSON 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol1" value="체크"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="이름"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol3" value="emptyCol(빈값)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="생년월일"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // chk : inputType="checkbox" - 원본값 1/0, trueValue/falseValue 로 체크 상태 결정
    strTarget += '<w2:column width="100" style="" inputType="checkbox" id="chk" dataList="chk" trueValue="1" falseValue="0"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="emptyCol" dataList="emptyCol"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="birth" dataList="birth"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getUncheckedJSON 확인 : chk(checkbox Column ID) 로 호출 → 체크 해제된 Row(1,3) 데이터를 JSON 객체 배열로 반환
//  con_dataListOption 선택값(DataList 속성)에 따라 반환 객체의 형태가 달라짐:
//   - rowNumData=true       → 각 객체 마지막 Key 로 "rowNum"(인덱스+1) 추가
//   - nullYN=true+null       → emptyCol 빈 문자열이 null 값으로 반환
//   - nullYN=true+exclude    → emptyCol 빈 문자열 Key 가 JSON 에서 제외
//   - useNull=false          → emptyCol 의 null 값이 빈 문자열("")로 반환
scwin.btn_getUncheckedJSON_onclick = function () {
    let colId = "chk";
    let rtn = target1.getUncheckedJSON(colId);
    wf_body_bottom.getObj("scwin").setReturnValue("[" + con_dataListOption.getText() + "] getUncheckedJSON('" + colId + "') : " + JSON.stringify(rtn));
}
